    private String simplify(Node n){
        if(isSimpleExpr(n)){
            return n.accept(this,null);
        }
        else{
            String tmp = newTemp();
            String val = n.accept(this,null);
            emit("MOVE " + tmp + " " + val + "\n");
            return tmp;
        }
    }

